#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<pair<int, int>> p1(n), p2(m);
    vector<vector<int>> v1(n), v2(m);

    for (auto &[a, b] : p1) cin >> a >> b;
    for (auto &[a, b] : p2) cin >> a >> b;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (p1[i].first == p2[j].first &&
                p1[i].second != p2[j].second) {
                v1[i].push_back(p1[i].first);
                v2[j].push_back(p2[j].first);
            }
            if (p1[i].first == p2[j].second &&
                p1[i].second != p2[j].first) {
                v1[i].push_back(p1[i].first);
                v2[j].push_back(p2[j].second);
            }
            if (p1[i].second == p2[j].first &&
                p1[i].first != p2[j].second) {
                v1[i].push_back(p1[i].second);
                v2[j].push_back(p2[j].first);
            }
            if (p1[i].second == p2[j].second &&
                p1[i].first != p2[j].first) {
                v1[i].push_back(p1[i].second);
                v2[j].push_back(p2[j].second);
            }
        }
    }

    for (const auto &values : v1) {
        for (size_t j = 1; j < values.size(); ++j) {
            if (values[j] != values[0]) {
                cout << -1 << '\n';
                return 0;
            }
        }
    }

    for (const auto &values : v2) {
        for (size_t j = 1; j < values.size(); ++j) {
            if (values[j] != values[0]) {
                cout << -1 << '\n';
                return 0;
            }
        }
    }

    bool found = false;
    int candidate = 0;

    for (const auto &values : v1) {
        for (int value : values) {
            if (!found) {
                candidate = value;
                found = true;
            } else if (value != candidate) {
                cout << 0 << '\n';
                return 0;
            }
        }
    }

    cout << (found ? candidate : 0) << '\n';
    return 0;
}

